"""
Python bindings for NLM (Neural Learning Machine)

This module provides Python bindings for the NLM neural simulation framework
using pybind11. It exposes the core C++ API to Python users with a
Pythonic interface.

Usage:
    from nlm import Brain, Simulation, Config
    brain = Brain(neuron_count=100, random_seed=42)
    brain.initialize()
    brain.step()
"""

import numpy as np
